<?php
require_once __DIR__ . '/../LOGIN/conexion.php';
$numero = preg_replace('/\\D+/', '', (string)getenv('WHATSAPP_NUMBER'));
$correo = trim((string)getenv('CONTACT_EMAIL'));
$direccion = trim((string)getenv('REFUGIO_DIRECCION'));
$waUrl = $numero !== '' ? 'https://wa.me/'.$numero : '';
$ayudaUrl = $numero !== '' ? $waUrl.'?text='.rawurlencode('Hola, quiero dar a conocer a un perro que necesita apoyo de la fundación. ¿Puedo compartirles su caso?') : '';
$mapQuery = $direccion !== '' ? $direccion : 'Refugio de animales, México';
$mapUrl = 'https://www.google.com/maps/search/?api=1&query='.rawurlencode($mapQuery);
$embedUrl = 'https://maps.google.com/maps?q='.rawurlencode($mapQuery).'&output=embed';
?>
